import{_ as o,l as s,o as e,c as i,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"安全等级与 RSP","description":"","frontmatter":{"title":"安全等级与 RSP","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/safety-levels-rsp.md","filePath":"llm/safety-levels-rsp.md","lastUpdated":1789023840000}'),c={name:"llm/safety-levels-rsp.md"};function m(A,a,E,_,f,u){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="安全等级与-rsp" tabindex="-1">安全等级与 RSP <a class="header-anchor" href="#安全等级与-rsp" aria-label="Permalink to &quot;安全等级与 RSP&quot;">​</a></h1><div class="epigraph"><p>能力越过某条线，部署与研发要换一套约束，而不是继续用同一张模型卡。等级是政策对象，不是又一个排行榜分数。</p><footer>—— Anthropic Responsible Scaling Policy 一类公开框架；对照危险能力评测</footer></div><p><a href="/llm/model-fingerprinting">上一课</a>是检测。本课把对齐失效收成<strong>部署政策</strong>：安全等级与负责任扩展政策（RSP）——预先承诺：测到哪些危险能力，就触发哪些暂停、安全措施或外部报告。缺口不是再写一条越狱防御，而是承认能力会随规模跳变，政策必须先于跳变写好。后课部署后监控是等级制度的运行时部分。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/dangerous-capability-eval">危险能力评测</a> 给出测量。若测量不绑定决策，只变成论文表。RSP 要回答：谁有权部署、需要哪些防护（隔离、监控、访问控制）、何时升级评测深度。缺口是把「我们会小心」写成可审计的阈值与动作，哪怕阈值会错、会改。</p><p><span class="marginnote">公开 RSP 是自我承诺，不是监管。本课只讲结构：能力带 → 触发 → 措施。不把任何公司的具体 ASL 编号当成物理常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>结构四段。<strong>能力带</strong>：例如网络攻击辅助、自主研发、生物误用（只作为评测类别名，不写操作细节）。<strong>评测方案</strong>：独立红队、持有集、是否允许最大引出。<strong>触发</strong>：达到带则停止扩大部署或停止进一步训练，直到措施到位。<strong>措施</strong>：物理与逻辑隔离、客户限制、监控（下一课）。报告要可复现到「用了哪套题、哪次解码」。</p>',8)),(e(),n(h,null,{default:r(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20EVAL%5B%22%E5%8D%B1%E9%99%A9%E8%83%BD%E5%8A%9B%E8%AF%84%E6%B5%8B%22%5D%20--%3E%20BAND%5B%22%E8%90%BD%E5%85%A5%E5%93%AA%E4%B8%80%E5%B8%A6%22%5D%0A%20%20BAND%20--%3E%20ACT%5B%22%E6%9A%82%E5%81%9C%20%2F%20%E6%8E%AA%E6%96%BD%20%2F%20%E9%83%A8%E7%BD%B2%22%5D%0A%20%20ACT%20--%3E%20MON%5B%22%E9%83%A8%E7%BD%B2%E5%90%8E%E7%9B%91%E6%8E%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>规模与训练计算使能力前移；若政策只在事后写，跳变窗口里模型已经在用户手里。预先承诺把「再训 2× 计算」从纯工程决策变成带门槛的决策。误报（评测过严）会拖慢部署；漏报会让提取与误用赶上无措施的接口——见 <a href="/llm/model-extraction-attack">模型提取</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供任何危险能力的操作指南。等级名称以各组织公开文档为准，本栏不发明一套新 ASL。下一课写监控：等级触发之后，线上仍要看漂移与滥用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RSP：能力带 → 评测 → 触发动作，预先承诺。</li><li>分数不绑定决策就只是排行榜。</li><li>公开政策是审计对象，不是物理定律。</li><li>出处：Anthropic RSP 等公开框架；危险能力评测课。</li></ul>',6))])}const S=o(c,[["render",m]]);export{P as __pageData,S as default};
